package domain

import "testing"
func TestProfileTabIdentity(t *testing.T){p,e:=ParseProfileID("123e4567-e89b-42d3-a456-426614174000");if e!=nil{t.Fatal(e)};if _,e=ParseProfileID("bad");e==nil{t.Fatal("malformed ID accepted")};a:=TabIdentity{p,ContextNormal,7};b:=TabIdentity{p,ContextPrivate,7};if a.Equal(b){t.Fatal("context collision")}}
func TestProjectionSnapshotAtomicityAndRevision(t *testing.T){p,_:=ParseProfileID("123e4567-e89b-42d3-a456-426614174000");epoch:="123e4567-e89b-42d3-a456-426614174001";s:=NewProjection(p,ContextNormal);r:=EligibleTabRecord{ProfileID:p,ContextKind:ContextNormal,TabIdentity:TabIdentity{p,ContextNormal,7},WindowID:1,TitleDisplay:"one",TitleSearch:"one",URLSearch:"https://example.test",URLDisplay:"example.test",DomainDisplay:"example.test",DomainSearch:"example.test",Eligible:true,ProjectionEpoch:epoch};if e:=s.Snapshot(epoch,[]EligibleTabRecord{r});e!=nil{t.Fatal(e)};bad:=r;bad.TabIdentity.TabID=8;bad.ProfileID="bad";if e:=s.Snapshot(epoch,[]EligibleTabRecord{r,bad});e==nil{t.Fatal("invalid snapshot accepted")};if len(s.Records)!=1||s.Revision!=1{t.Fatal("partial snapshot mutation")};r.TabIdentity.TabID=8;ev:=ProjectionEvent{ProfileID:p,ContextKind:ContextNormal,Epoch:epoch,Sequence:2,PreviousRevision:1,Operation:"upsert",Identity:r.TabIdentity,Record:&r};if got:=s.Apply(ev);got!="APPLIED"{t.Fatal(got)};if got:=s.Apply(ev);got!="DUPLICATE"{t.Fatal(got)};ev.Sequence=4;if got:=s.Apply(ev);got!="SNAPSHOT_REQUIRED"{t.Fatal(got)};if len(s.Records)!=2||s.Revision!=2{t.Fatal("invalid event mutated state")}}
func TestActivationRetention(t *testing.T){p,_:=ParseProfileID("123e4567-e89b-42d3-a456-426614174000");rows:=make([]ActivationMetadata,502);for i:=range rows{rows[i]=ActivationMetadata{ProfileID:p,ContextKind:ContextNormal,ActivatedAt:1000+int64(i),StorageSequence:uint64(i)}};rows[0].ContextKind=ContextPrivate;got:=RetainActivations(rows,1600);if len(got)!=500||got[0].StorageSequence!=2{t.Fatalf("retention result %d first %d",len(got),got[0].StorageSequence)}}
